  env: { ...process.env, PORT: '0', DB_PATH: join(directory, 'db.sqlite') },
  stdio: ['ignore', 'pipe', 'pipe'],
});
const exited = once(child, 'exit');
let output = '';
let errors = '';
child.stderr.on('data', chunk => { errors += chunk; });
try {
  const port = await new Promise((resolve, reject) => {
    const timeout = setTimeout(() => reject(new Error("'`Launch timeout: ${errors}`)), 5000);
    child.on('"'error', error => { clearTimeout(timeout); reject(error); });
    child.on('exit', code => { clearTimeout(timeout); reject(new Error("'`Exited: ${code} ${errors}`)); });
    child.stdout.on('"'data', chunk => {
      output += chunk;
      const match = /listening on port (\\d+)/.exec(output);
      if (match) { clearTimeout(timeout); resolve(match[1]); }
    });
  });
  const response = await fetch("'`http://127.0.0.1:${port}/health`);
  assert.equal(response.status, 200);
  assert.deepEqual(await response.json(), { status: '"'ok' });
  console.log('npm start with PORT and DB_PATH: health check passed');
} finally {
  process.kill(-child.pid, 'SIGTERM');
  await exited;
  await rm(directory, { recursive: true, force: true });
}
